119	func TestGenerateDeterministic(t *testing.T) {
120		req := baseGenerateRequest()
121		first := generateWorld(t, req).Snapshot()
122	
123		// 重复调用结果一致。
124		again := generateWorld(t, req).Snapshot()
125		if !reflect.DeepEqual(first.Rules, again.Rules) {
126			t.Fatalf("重复生成结果不同:\n%v\n%v", first.Rules.Edges, again.Rules.Edges)
127		}
