58		if err != nil {
59			t.Fatalf("并发后最新记录应完好: %v", err)
60		}
61		if rec.Parent != info.ID {
62			t.Fatalf("胜出记录的父应为 %s，得到 %s", info.ID, rec.Parent)
63		}
64		hist, err := a2.History("s")
65		if err != nil {
66			t.Fatal(err)
67		}
68		if len(hist) != 2 {
