74	// 成功退出码 0；冲突退出码 3；其他错误退出码 1。
75	func helperConcurrentReplace() {
76		dir := os.Getenv("WORLD_TEST_DIR")
77		parent := RecordID(os.Getenv("WORLD_TEST_PARENT"))
