470		if err := writeRecord(a.dir, env); err != nil {
471			t.Fatal(err)
472		}
473		return id
474	}
475	
476	// updatePointer 模拟一个遵循磁盘格式的写入器：新记录已完整落盘后原子
477	// 更新槽指针，并把新记录按保存次序前置到历史索引。
478	func updatePointer(t *testing.T, a *Archive, slot string, id RecordID) {
